-- =============================================================================
-- REDES CYAN · CIUDAD DELGADO
-- Base de datos para Supabase (PostgreSQL 15+ con PostGIS)
--
-- Cómo usarlo: Supabase > SQL Editor > New query > pegar todo > Run.
-- El script se puede volver a ejecutar: crea lo que falta y actualiza
-- catálogos, zonas y cantones sin borrar redes ni personas.
--
-- Contenido
--   1. Extensiones
--   2. Catálogos: ejes, zonas, cantones y barrios
--   3. Redes, comunidades y personas (responsable + hasta 20 integrantes)
--   4. Reglas automáticas (zona y cantón por ubicación, fechas, límites)
--   5. Función guardar_red() para guardar una red completa en un paso
--   6. Vistas para reportes y exportación a Excel
--   7. Seguridad (RLS) y almacenamiento de logos
--   8. Datos iniciales: ejes, 18 zonas y 11 cantones/barrios con sus límites
-- =============================================================================

-- 1. EXTENSIONES ---------------------------------------------------------------
create extension if not exists postgis with schema extensions;
create extension if not exists pgcrypto with schema extensions;

-- 2. CATÁLOGOS -----------------------------------------------------------------
create table if not exists public.ejes (
  id      smallint primary key,
  nombre  text not null unique
);
comment on table public.ejes is 'Ejes de trabajo de las redes (hoja EJES de la plantilla).';

create table if not exists public.zonas (
  numero  smallint primary key check (numero between 1 and 99),
  geom    extensions.geometry(MultiPolygon, 4326) not null
);
comment on table public.zonas is 'Zonas del distrito Ciudad Delgado, trazadas desde el mapa oficial de zonas.';
-- Punto donde va el rótulo "ZONA N" en el mapa (mismo lugar que en el mapa oficial).
alter table public.zonas add column if not exists etiqueta extensions.geometry(Point, 4326);
create index if not exists zonas_geom_gix on public.zonas using gist (geom);

create table if not exists public.cantones (
  id      smallint primary key,
  nombre  text not null unique,
  tipo    text not null default 'canton' check (tipo in ('canton', 'barrio')),
  geom    extensions.geometry(MultiPolygon, 4326) not null
);
comment on table public.cantones is 'Cantones y barrios de Ciudad Delgado (KMZ DIVISION_DE_CANTONES).';
create index if not exists cantones_geom_gix on public.cantones using gist (geom);

-- 3. REDES, COMUNIDADES Y PERSONAS ----------------------------------------------
create table if not exists public.redes (
  id               uuid primary key default gen_random_uuid(),
  nombre           text not null check (char_length(btrim(nombre)) between 3 and 80),
  lema             text not null check (char_length(btrim(lema)) between 3 and 140),
  logo_path        text,                     -- ruta del archivo en el bucket "logos-redes"
  departamento     text not null default 'SAN SALVADOR',
  municipio        text not null default 'San Salvador Centro',
  distrito         text not null default 'Ciudad Delgado',
  zona             smallint references public.zonas (numero),
  canton_id        smallint references public.cantones (id),
  centro_votacion  text not null check (char_length(btrim(centro_votacion)) >= 3),
  eje_id           smallint not null references public.ejes (id),
  latitud          double precision not null check (latitud between -90 and 90),
  longitud         double precision not null check (longitud between -180 and 180),
  ubicacion        extensions.geometry(Point, 4326)
                   generated always as (extensions.st_setsrid(extensions.st_makepoint(longitud, latitud), 4326)) stored,
  zona_detectada   smallint,                 -- zona donde cae el punto según el mapa
  creado_por       uuid default auth.uid() references auth.users (id) on delete set null,
  creado_en        timestamptz not null default now(),
  actualizado_en   timestamptz not null default now()
);
comment on table public.redes is 'Una fila por red cyan. Las personas están en public.personas.';
comment on column public.redes.zona is 'Zona asignada. Si se deja vacía se llena con la zona donde cae el punto.';
create unique index if not exists redes_nombre_uidx on public.redes (lower(btrim(nombre)));
create index if not exists redes_ubicacion_gix on public.redes using gist (ubicacion);
create index if not exists redes_zona_idx on public.redes (zona);
create index if not exists redes_canton_idx on public.redes (canton_id);
create index if not exists redes_eje_idx on public.redes (eje_id);

create table if not exists public.red_comunidades (
  id      bigint generated always as identity primary key,
  red_id  uuid not null references public.redes (id) on delete cascade,
  nombre  text not null check (char_length(btrim(nombre)) >= 2)
);
comment on table public.red_comunidades is 'Comunidades que abarca cada red (al menos una).';
create unique index if not exists red_comunidades_uidx on public.red_comunidades (red_id, lower(btrim(nombre)));

create table if not exists public.personas (
  id        uuid primary key default gen_random_uuid(),
  red_id    uuid not null references public.redes (id) on delete cascade,
  rol       text not null check (rol in ('responsable', 'integrante')),
  posicion  smallint not null,   -- 0 = responsable, 1..20 = integrantes
  nombre    text not null check (char_length(btrim(nombre)) >= 5),
  dui       text not null check (dui ~ '^\d{8}-\d$'),
  telefono  text not null check (telefono ~ '^[267]\d{3}-\d{4}$'),
  creado_en timestamptz not null default now(),
  constraint personas_posicion_ck check (
    (rol = 'responsable' and posicion = 0) or (rol = 'integrante' and posicion between 1 and 20)
  ),
  constraint personas_dui_uk unique (dui),
  constraint personas_red_pos_uk unique (red_id, posicion)
);
comment on table public.personas is 'Responsable (posición 0) e integrantes (posiciones 1 a 20) de cada red. Un DUI solo puede estar en una red.';
create index if not exists personas_red_idx on public.personas (red_id);

-- 4. REGLAS AUTOMÁTICAS ---------------------------------------------------------

-- Dígito verificador del DUI (se usa en las vistas para marcar números dudosos).
create or replace function public.dui_valido(p_dui text)
returns boolean
language sql immutable
set search_path = ''
as $$
  select case when p_dui ~ '^\d{8}-\d$' then
    (10 - (
      (substr(p_dui,1,1)::int * 9 + substr(p_dui,2,1)::int * 8 + substr(p_dui,3,1)::int * 7 + substr(p_dui,4,1)::int * 6 +
       substr(p_dui,5,1)::int * 5 + substr(p_dui,6,1)::int * 4 + substr(p_dui,7,1)::int * 3 + substr(p_dui,8,1)::int * 2) % 10
    )) % 10 = substr(p_dui,10,1)::int
  else false end;
$$;

-- Zona y cantón según la ubicación; normaliza textos; mantiene la fecha de cambio.
create or replace function public.redes_antes_de_guardar()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_punto extensions.geometry := extensions.st_setsrid(extensions.st_makepoint(new.longitud, new.latitud), 4326);
begin
  new.nombre := btrim(regexp_replace(new.nombre, '\s+', ' ', 'g'));
  new.lema := btrim(regexp_replace(new.lema, '\s+', ' ', 'g'));
  new.centro_votacion := btrim(regexp_replace(new.centro_votacion, '\s+', ' ', 'g'));

  if tg_op = 'INSERT' or new.latitud is distinct from old.latitud or new.longitud is distinct from old.longitud then
    select z.numero into new.zona_detectada
      from public.zonas z where extensions.st_intersects(z.geom, v_punto) order by z.numero limit 1;
    select c.id into new.canton_id
      from public.cantones c where extensions.st_intersects(c.geom, v_punto) order by c.id limit 1;
  end if;
  if new.zona is null then
    new.zona := new.zona_detectada;
  end if;

  if tg_op = 'UPDATE' then
    new.creado_en := old.creado_en;
    new.creado_por := old.creado_por;
  end if;
  new.actualizado_en := now();
  return new;
end;
$$;

drop trigger if exists redes_antes_de_guardar on public.redes;
create trigger redes_antes_de_guardar
  before insert or update on public.redes
  for each row execute function public.redes_antes_de_guardar();

create or replace function public.personas_antes_de_guardar()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.nombre := upper(btrim(regexp_replace(new.nombre, '\s+', ' ', 'g')));
  return new;
end;
$$;

drop trigger if exists personas_antes_de_guardar on public.personas;
create trigger personas_antes_de_guardar
  before insert or update on public.personas
  for each row execute function public.personas_antes_de_guardar();

create or replace function public.comunidades_antes_de_guardar()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.nombre := btrim(regexp_replace(new.nombre, '\s+', ' ', 'g'));
  new.nombre := upper(left(new.nombre, 1)) || substr(new.nombre, 2);
  return new;
end;
$$;

drop trigger if exists comunidades_antes_de_guardar on public.red_comunidades;
create trigger comunidades_antes_de_guardar
  before insert or update on public.red_comunidades
  for each row execute function public.comunidades_antes_de_guardar();

-- 5. GUARDAR UNA RED COMPLETA ---------------------------------------------------
-- Guarda (o actualiza) la red, sus comunidades, el responsable y los integrantes
-- en una sola transacción. Si algo falla, no se guarda nada.
--
-- Ejemplo desde la app (supabase-js):
--   const { data: redId, error } = await supabase.rpc('guardar_red', { p_red: {
--     id: null,                       // o el id de la red para editarla
--     nombre: 'Red Cyan Los Ángeles', lema: 'Juntos por nuestra colonia',
--     logo_path: 'redes/abc.webp', centro_votacion: 'Centro Escolar ...',
--     eje: 'TECNOLOGIA', zona: 8, latitud: 13.7301, longitud: -89.1712,
--     comunidades: ['Colonia Los Ángeles', 'Barrio Paleca'],
--     responsable: { nombre: 'Juan Pérez', dui: '01234567-8', telefono: '7123-4567' },
--     integrantes: [ { nombre: 'María López', dui: '04567891-2', telefono: '6123-4567' } ]
--   }});
create or replace function public.guardar_red(p_red jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id   uuid := nullif(p_red->>'id', '')::uuid;
  v_eje  smallint;
  v_resp jsonb := p_red->'responsable';
  v_ints jsonb := coalesce(p_red->'integrantes', '[]'::jsonb);
  v_coms jsonb := coalesce(p_red->'comunidades', '[]'::jsonb);
  v_i    int := 0;
  v_m    jsonb;
  v_dup  text;
  v_otra text;
begin
  select id into v_eje from public.ejes where nombre = upper(btrim(p_red->>'eje'));
  if v_eje is null then
    raise exception 'Eje no válido: %', p_red->>'eje' using errcode = '22023';
  end if;
  if jsonb_typeof(v_coms) <> 'array' or jsonb_array_length(v_coms) = 0 then
    raise exception 'La red debe tener al menos una comunidad.' using errcode = '22023';
  end if;
  if v_resp is null then
    raise exception 'Falta el responsable de la red.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_ints) <> 'array' or jsonb_array_length(v_ints) > 20 then
    raise exception 'Una red puede tener como máximo 20 integrantes.' using errcode = '22023';
  end if;

  -- DUI repetidos dentro de la red o ya usados en otra red.
  select d into v_dup from (
    select v_resp->>'dui' as d
    union all select value->>'dui' from jsonb_array_elements(v_ints)
  ) x group by d having count(*) > 1 limit 1;
  if v_dup is not null then
    raise exception 'El DUI % está repetido dentro de la red.', v_dup using errcode = '23505';
  end if;
  select p.dui, r.nombre into v_dup, v_otra
  from public.personas p join public.redes r on r.id = p.red_id
  where p.red_id is distinct from v_id
    and p.dui in (select v_resp->>'dui' union all select value->>'dui' from jsonb_array_elements(v_ints))
  limit 1;
  if v_dup is not null then
    raise exception 'El DUI % ya está registrado en la red "%".', v_dup, v_otra using errcode = '23505';
  end if;

  if v_id is null then
    insert into public.redes (nombre, lema, logo_path, centro_votacion, eje_id, zona, latitud, longitud)
    values (p_red->>'nombre', p_red->>'lema', nullif(p_red->>'logo_path', ''), p_red->>'centro_votacion', v_eje,
            nullif(p_red->>'zona', '')::smallint, (p_red->>'latitud')::double precision, (p_red->>'longitud')::double precision)
    returning id into v_id;
  else
    update public.redes set
      nombre = p_red->>'nombre', lema = p_red->>'lema', logo_path = nullif(p_red->>'logo_path', ''),
      centro_votacion = p_red->>'centro_votacion', eje_id = v_eje, zona = nullif(p_red->>'zona', '')::smallint,
      latitud = (p_red->>'latitud')::double precision, longitud = (p_red->>'longitud')::double precision
    where id = v_id;
    if not found then
      raise exception 'No existe la red % o no tiene permiso para editarla.', v_id using errcode = 'P0002';
    end if;
    delete from public.red_comunidades where red_id = v_id;
    delete from public.personas where red_id = v_id;
  end if;

  insert into public.red_comunidades (red_id, nombre)
  select distinct on (lower(btrim(c))) v_id, c
  from jsonb_array_elements_text(v_coms) as c
  where btrim(c) <> '';

  insert into public.personas (red_id, rol, posicion, nombre, dui, telefono)
  values (v_id, 'responsable', 0, v_resp->>'nombre', v_resp->>'dui', v_resp->>'telefono');

  for v_m in select value from jsonb_array_elements(v_ints) loop
    v_i := v_i + 1;
    insert into public.personas (red_id, rol, posicion, nombre, dui, telefono)
    values (v_id, 'integrante', v_i, v_m->>'nombre', v_m->>'dui', v_m->>'telefono');
  end loop;

  return v_id;
exception
  when unique_violation then
    declare
      v_det text; v_con text;
    begin
      get stacked diagnostics v_det = pg_exception_detail, v_con = constraint_name;
      if v_con = 'personas_dui_uk' then
        raise exception 'Uno de los DUI ya está registrado en otra red.' using errcode = '23505';
      elsif v_con = 'redes_nombre_uidx' then
        raise exception 'Ya existe una red con el nombre "%".', p_red->>'nombre' using errcode = '23505';
      elsif v_con = 'red_comunidades_uidx' then
        raise exception 'Hay una comunidad repetida.' using errcode = '23505';
      end if;
      raise;
    end;
end;
$$;

-- 6. VISTAS ---------------------------------------------------------------------

-- Una fila por red, con todo lo necesario para el mapa y el padrón.
create or replace view public.v_redes
with (security_invoker = true) as
select
  r.id, r.nombre, r.lema, r.logo_path,
  r.departamento, r.municipio, r.distrito,
  r.zona, r.zona_detectada, (r.zona_detectada is not null and r.zona is distinct from r.zona_detectada) as zona_difiere,
  c.nombre as canton, e.nombre as eje, r.centro_votacion,
  r.latitud, r.longitud,
  resp.nombre as responsable, resp.dui as responsable_dui, resp.telefono as responsable_telefono,
  (select count(*) from public.personas p where p.red_id = r.id and p.rol = 'integrante')::int as integrantes,
  coalesce((select array_agg(rc.nombre order by rc.id) from public.red_comunidades rc where rc.red_id = r.id), '{}') as comunidades,
  r.creado_en, r.actualizado_en
from public.redes r
join public.ejes e on e.id = r.eje_id
left join public.cantones c on c.id = r.canton_id
left join public.personas resp on resp.red_id = r.id and resp.rol = 'responsable';

-- Una fila por persona con las columnas de la plantilla original (para Excel).
create or replace view public.v_personas_export
with (security_invoker = true) as
select
  r.departamento   as "Departamento",
  r.municipio      as "Municipio",
  r.distrito       as "Distrito",
  r.zona           as "Zona",
  r.centro_votacion as "Centro de votacion",
  e.nombre         as "Eje",
  p.nombre         as "Nombre",
  p.dui            as "Dui",
  p.telefono       as "Telefono",
  initcap(p.rol)   as "Rol",
  r.nombre         as "Nombre de la red",
  c.nombre         as "Canton / Barrio",
  r.latitud        as "Latitud",
  r.longitud       as "Longitud",
  public.dui_valido(p.dui) as "DUI verificado"
from public.personas p
join public.redes r on r.id = p.red_id
join public.ejes e on e.id = r.eje_id
left join public.cantones c on c.id = r.canton_id
order by r.zona, r.centro_votacion, r.nombre, p.posicion;

-- Totales por zona (incluye zonas sin redes).
create or replace view public.v_resumen_zonas
with (security_invoker = true) as
select
  z.numero as zona,
  count(distinct r.id)::int as redes,
  count(p.id)::int as personas
from public.zonas z
left join public.redes r on r.zona = z.numero
left join public.personas p on p.red_id = r.id
group by z.numero
order by z.numero;

-- Zonas y cantones como GeoJSON para dibujarlos en el mapa de la app.
create or replace view public.v_mapa_capas
with (security_invoker = true) as
select 'zona' as capa, numero::text as nombre, extensions.st_asgeojson(geom, 6)::jsonb as geojson from public.zonas
union all
select 'canton', nombre, extensions.st_asgeojson(geom, 6)::jsonb from public.cantones;

-- 7. SEGURIDAD -----------------------------------------------------------------
-- Solo usuarios con sesión iniciada (authenticated) ven y cargan datos.
-- Los visitantes sin sesión (anon) no ven nada: las redes contienen DUI y teléfonos.
-- Cualquier usuario con sesión puede crear y editar redes; solo quien creó una red
-- puede borrarla.

alter table public.ejes enable row level security;
alter table public.zonas enable row level security;
alter table public.cantones enable row level security;
alter table public.redes enable row level security;
alter table public.red_comunidades enable row level security;
alter table public.personas enable row level security;

drop policy if exists "leer ejes" on public.ejes;
create policy "leer ejes" on public.ejes for select to authenticated using (true);
drop policy if exists "leer zonas" on public.zonas;
create policy "leer zonas" on public.zonas for select to authenticated using (true);
drop policy if exists "leer cantones" on public.cantones;
create policy "leer cantones" on public.cantones for select to authenticated using (true);

drop policy if exists "leer redes" on public.redes;
create policy "leer redes" on public.redes for select to authenticated using (true);
drop policy if exists "crear redes" on public.redes;
create policy "crear redes" on public.redes for insert to authenticated with check (true);
drop policy if exists "editar redes" on public.redes;
create policy "editar redes" on public.redes for update to authenticated using (true) with check (true);
drop policy if exists "borrar redes propias" on public.redes;
create policy "borrar redes propias" on public.redes for delete to authenticated using (creado_por = (select auth.uid()));

drop policy if exists "gestionar comunidades" on public.red_comunidades;
create policy "gestionar comunidades" on public.red_comunidades for all to authenticated using (true) with check (true);
drop policy if exists "gestionar personas" on public.personas;
create policy "gestionar personas" on public.personas for all to authenticated using (true) with check (true);

revoke all on public.ejes, public.zonas, public.cantones, public.redes, public.red_comunidades, public.personas from anon;
revoke all on public.v_redes, public.v_personas_export, public.v_resumen_zonas, public.v_mapa_capas from anon;
grant select on public.ejes, public.zonas, public.cantones to authenticated;
grant select, insert, update, delete on public.redes, public.red_comunidades, public.personas to authenticated;
grant select on public.v_redes, public.v_personas_export, public.v_resumen_zonas, public.v_mapa_capas to authenticated;
revoke execute on function public.guardar_red(jsonb) from public, anon;
grant execute on function public.guardar_red(jsonb) to authenticated;

-- Logos: bucket público para mostrarlos en el mapa; solo usuarios con sesión suben o cambian.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('logos-redes', 'logos-redes', true, 1048576, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "logos: subir" on storage.objects;
create policy "logos: subir" on storage.objects for insert to authenticated
  with check (bucket_id = 'logos-redes');
drop policy if exists "logos: cambiar" on storage.objects;
create policy "logos: cambiar" on storage.objects for update to authenticated
  using (bucket_id = 'logos-redes') with check (bucket_id = 'logos-redes');
drop policy if exists "logos: borrar propios" on storage.objects;
create policy "logos: borrar propios" on storage.objects for delete to authenticated
  using (bucket_id = 'logos-redes' and owner = (select auth.uid()));

-- 8. DATOS INICIALES --------------------------------------------------------------
insert into public.ejes (id, nombre) values
  (1, 'ARTE Y CULTURA'),
  (2, 'EMPRENDIMIENTO'),
  (3, 'DEPORTE'),
  (4, 'TECNOLOGIA'),
  (5, 'MEDIOAMBIENTE')
on conflict (id) do update set nombre = excluded.nombre;
