on conflict (id) do update set nombre = excluded.nombre, tipo = excluded.tipo, geom = excluded.geom;

-- Recalcular zona y cantón de las redes que ya existan (por si se actualizaron los límites).
update public.redes r set
  zona_detectada = (select z.numero from public.zonas z where extensions.st_intersects(z.geom, r.ubicacion) order by z.numero limit 1),
  canton_id = (select c.id from public.cantones c where extensions.st_intersects(c.geom, r.ubicacion) order by c.id limit 1);

-- =============================================================================
-- 9. ACTIVIDADES Y DOCUMENTOS DE SEGUIMIENTO
-- =============================================================================
create table if not exists public.tipos_actividad (
  id      smallint primary key,
  nombre  text not null unique
);
comment on table public.tipos_actividad is 'Tipos de actividad comunitaria.';

create table if not exists public.actividades (
  id               uuid primary key default gen_random_uuid(),
  tipo_id          smallint not null references public.tipos_actividad (id),
  titulo           text not null check (char_length(btrim(titulo)) between 3 and 120),
  fecha            date not null,
  hora             time,
  estado           text not null default 'programada' check (estado in ('programada', 'realizada', 'cancelada')),
  red_id           uuid references public.redes (id) on delete set null,
  lugar            text,                       -- referencia: colonia, pasaje, parque...
  descripcion      text,
  participantes    integer check (participantes is null or participantes >= 0),
  beneficiarios    integer check (beneficiarios is null or beneficiarios >= 0),
  latitud          double precision not null check (latitud between -90 and 90),
  longitud         double precision not null check (longitud between -180 and 180),
  ubicacion        extensions.geometry(Point, 4326)
                   generated always as (extensions.st_setsrid(extensions.st_makepoint(longitud, latitud), 4326)) stored,
  zona             smallint references public.zonas (numero),
  canton_id        smallint references public.cantones (id),
  creado_por       uuid default auth.uid() references auth.users (id) on delete set null,
  creado_en        timestamptz not null default now(),
  actualizado_en   timestamptz not null default now()
);
comment on table public.actividades is 'Actividades comunitarias ubicadas en el mapa (jornadas, fiestas, bacheos, etc.).';
create index if not exists actividades_ubicacion_gix on public.actividades using gist (ubicacion);
create index if not exists actividades_fecha_idx on public.actividades (fecha desc);
create index if not exists actividades_tipo_idx on public.actividades (tipo_id);
create index if not exists actividades_red_idx on public.actividades (red_id);
create index if not exists actividades_zona_idx on public.actividades (zona);

create table if not exists public.actividad_documentos (
  id            uuid primary key default gen_random_uuid(),
  actividad_id  uuid not null references public.actividades (id) on delete cascade,
  categoria     text not null default 'otro'
                check (categoria in ('fotografia', 'acta', 'asistencia', 'informe', 'otro')),
  descripcion   text,
  archivo_path  text not null unique,          -- ruta en el bucket "documentos-actividades"
  nombre_archivo text not null,
  tipo_mime     text,
  tamano_bytes  bigint check (tamano_bytes is null or tamano_bytes >= 0),
  subido_por    uuid default auth.uid() references auth.users (id) on delete set null,
  subido_en     timestamptz not null default now()
);
comment on table public.actividad_documentos is 'Documentos de seguimiento de cada actividad (fotos, actas, listas de asistencia, informes).';
create index if not exists actividad_documentos_act_idx on public.actividad_documentos (actividad_id);

-- Zona y cantón según la ubicación; fecha de cambio.
create or replace function public.actividades_antes_de_guardar()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_punto extensions.geometry := extensions.st_setsrid(extensions.st_makepoint(new.longitud, new.latitud), 4326);
begin
  new.titulo := btrim(regexp_replace(new.titulo, '\s+', ' ', 'g'));
  if tg_op = 'INSERT' or new.latitud is distinct from old.latitud or new.longitud is distinct from old.longitud then
    select z.numero into new.zona from public.zonas z where extensions.st_intersects(z.geom, v_punto) order by z.numero limit 1;
    select c.id into new.canton_id from public.cantones c where extensions.st_intersects(c.geom, v_punto) order by c.id limit 1;
  end if;
  if tg_op = 'UPDATE' then
    new.creado_en := old.creado_en;
    new.creado_por := old.creado_por;
  end if;
  new.actualizado_en := now();
  return new;
end;
$$;

drop trigger if exists actividades_antes_de_guardar on public.actividades;
create trigger actividades_antes_de_guardar
  before insert or update on public.actividades
  for each row execute function public.actividades_antes_de_guardar();

-- Vista para la lista y el mapa de actividades.
create or replace view public.v_actividades
with (security_invoker = true) as
select
  a.id, a.tipo_id, t.nombre as tipo, a.titulo, a.fecha, a.hora, a.estado,
  a.red_id, r.nombre as red, a.lugar, a.descripcion, a.participantes, a.beneficiarios,
  a.latitud, a.longitud, a.zona, c.nombre as canton,
  (select count(*) from public.actividad_documentos d where d.actividad_id = a.id)::int as documentos,
  a.creado_por, a.creado_en, a.actualizado_en
from public.actividades a
join public.tipos_actividad t on t.id = a.tipo_id
left join public.redes r on r.id = a.red_id
left join public.cantones c on c.id = a.canton_id;

-- Totales por tipo y estado.
create or replace view public.v_resumen_actividades
with (security_invoker = true) as
select t.nombre as tipo,
  count(a.id) filter (where a.estado = 'programada')::int as programadas,
  count(a.id) filter (where a.estado = 'realizada')::int as realizadas,
  coalesce(sum(a.participantes) filter (where a.estado = 'realizada'), 0)::int as participantes,
  coalesce(sum(a.beneficiarios) filter (where a.estado = 'realizada'), 0)::int as beneficiarios
from public.tipos_actividad t
left join public.actividades a on a.tipo_id = t.id
group by t.id, t.nombre
order by t.id;

alter table public.tipos_actividad enable row level security;
alter table public.actividades enable row level security;
alter table public.actividad_documentos enable row level security;

drop policy if exists "leer tipos de actividad" on public.tipos_actividad;
create policy "leer tipos de actividad" on public.tipos_actividad for select to authenticated using (true);

drop policy if exists "leer actividades" on public.actividades;
create policy "leer actividades" on public.actividades for select to authenticated using (true);
drop policy if exists "crear actividades" on public.actividades;
create policy "crear actividades" on public.actividades for insert to authenticated with check (true);
drop policy if exists "editar actividades" on public.actividades;
create policy "editar actividades" on public.actividades for update to authenticated using (true) with check (true);
drop policy if exists "borrar actividades propias" on public.actividades;
create policy "borrar actividades propias" on public.actividades for delete to authenticated using (creado_por = (select auth.uid()));

drop policy if exists "leer documentos" on public.actividad_documentos;
create policy "leer documentos" on public.actividad_documentos for select to authenticated using (true);
drop policy if exists "subir documentos" on public.actividad_documentos;
create policy "subir documentos" on public.actividad_documentos for insert to authenticated with check (true);
drop policy if exists "borrar documentos propios" on public.actividad_documentos;
create policy "borrar documentos propios" on public.actividad_documentos for delete to authenticated using (subido_por = (select auth.uid()));

revoke all on public.tipos_actividad, public.actividades, public.actividad_documentos from anon;
revoke all on public.v_actividades, public.v_resumen_actividades from anon;
grant select on public.tipos_actividad to authenticated;
grant select, insert, update, delete on public.actividades, public.actividad_documentos to authenticated;
grant select on public.v_actividades, public.v_resumen_actividades to authenticated;

-- Documentos: bucket privado (fotos de menores, listas con DUI...). Se ven con enlaces temporales.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('documentos-actividades', 'documentos-actividades', false, 20971520, array[
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'application/pdf',
  'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "documentos: ver" on storage.objects;
create policy "documentos: ver" on storage.objects for select to authenticated
  using (bucket_id = 'documentos-actividades');
drop policy if exists "documentos: subir" on storage.objects;
create policy "documentos: subir" on storage.objects for insert to authenticated
  with check (bucket_id = 'documentos-actividades');
drop policy if exists "documentos: borrar propios" on storage.objects;
create policy "documentos: borrar propios" on storage.objects for delete to authenticated
