-- =============================================================================
-- 10. USUARIOS Y ROLES
-- Solo un administrador crea usuarios (función "admin-usuarios"). Nadie puede
-- cambiar su propio rol: la tabla no acepta escrituras desde la app.
-- =============================================================================
create table if not exists public.perfiles (
  id              uuid primary key references auth.users (id) on delete cascade,
  nombre          text not null default '',
  correo          text,
  rol             text not null default 'usuario' check (rol in ('admin', 'usuario')),
  activo          boolean not null default true,
  creado_por      uuid references auth.users (id) on delete set null,
  creado_en       timestamptz not null default now(),
  actualizado_en  timestamptz not null default now()
);
comment on table public.perfiles is 'Nombre, rol (admin o usuario) y estado de cada cuenta.';

-- ¿El usuario de la sesión es administrador activo?
create or replace function public.es_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.perfiles p where p.id = auth.uid() and p.rol = 'admin' and p.activo);
$$;
revoke all on function public.es_admin() from public, anon;
grant execute on function public.es_admin() to authenticated;

-- Cada cuenta nueva recibe su perfil como "usuario". El rol nunca se toma de lo que envía quien se registra.
create or replace function public.crear_perfil_de_usuario()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.perfiles (id, nombre, correo)
  values (new.id, coalesce(btrim(new.raw_user_meta_data->>'nombre'), ''), new.email)
  on conflict (id) do nothing;
  return new;
end;
$$;
revoke all on function public.crear_perfil_de_usuario() from public, anon, authenticated;

drop trigger if exists crear_perfil_de_usuario on auth.users;
create trigger crear_perfil_de_usuario
  after insert on auth.users
  for each row execute function public.crear_perfil_de_usuario();

create or replace function public.perfiles_antes_de_guardar()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.nombre := btrim(regexp_replace(coalesce(new.nombre, ''), '\s+', ' ', 'g'));
  new.actualizado_en := now();
  return new;
end;
$$;
drop trigger if exists perfiles_antes_de_guardar on public.perfiles;
create trigger perfiles_antes_de_guardar
  before insert or update on public.perfiles
  for each row execute function public.perfiles_antes_de_guardar();

-- Perfiles para las cuentas que ya existían antes de este script.
insert into public.perfiles (id, correo, nombre)
select u.id, u.email, coalesce(btrim(u.raw_user_meta_data->>'nombre'), '')
from auth.users u
on conflict (id) do nothing;

alter table public.perfiles enable row level security;
drop policy if exists "ver mi perfil o todos si soy admin" on public.perfiles;
create policy "ver mi perfil o todos si soy admin" on public.perfiles
  for select to authenticated using (id = (select auth.uid()) or (select public.es_admin()));
-- Sin políticas de insert/update/delete: los cambios los hace solo la función "admin-usuarios".

revoke all on public.perfiles from anon, authenticated;
grant select on public.perfiles to authenticated;
grant all on public.perfiles to service_role;

