-- Enlazar las redes que ya existan con su centro de votación.
update public.redes r set centro_id = c.id
from public.centros_votacion c
where public.normalizar_texto(c.nombre) = public.normalizar_texto(r.centro_votacion)
  and r.centro_id is distinct from c.id;
